read_ok = InternetReadFile(request, data, 0x400, &bytes_read);
received = bytes_read;
while (read_ok
    && (int)(received + 0x400) <= 0x8000
    && bytes_read != 0) {
    read_ok = InternetReadFile(
        request,
        data + received,
        0x400,
        &bytes_read);
    received += bytes_read;
}

if (!read_ok) {
    console_printf(
        &console_log_queue,
        "Version Check: InternetReadFile failed.\n");
    console_printf(
        &console_log_queue,
        "Reason: %d\n",
        GetLastError());
    headers_length = 0x8000;
    InternetGetLastResponseInfoA(
        &response_error,
        data,
        &headers_length);
    console_printf(&console_log_queue, "Or: %s\n", data);
    goto cleanup;
}
if ((int)(received + 0x400) > 0x8000) {
    console_printf(
        &console_log_queue,
        "Warning: receiving too much data, breaking out..\n");
}

